package com.sih.portal.controller; import com.sih.portal.entity.*; import com.sih.portal.service.*; import java.util.*; import org.springframework.web.bind.annotation.*; import org.springframework.http.*; @RestController @RequestMapping("/api/v1/portal") public class PortalController{final PortalService s;public PortalController(PortalService s){this.s=s;}@GetMapping("/appointments")List<Appointment>a(){return s.appointments();}@PostMapping("/appointments")@ResponseStatus(HttpStatus.CREATED)Appointment b(@RequestBody Appointment q){return s.book(q);}@PostMapping("/appointments/{id}/confirm")Appointment c(@PathVariable Long id){return s.confirm(id);}@GetMapping("/teleconsultations")List<Teleconsultation>t(){return s.tele();}@PostMapping("/teleconsultations")@ResponseStatus(HttpStatus.CREATED)Teleconsultation n(@RequestBody Teleconsultation q){return s.create(q);}@PostMapping("/teleconsultations/{id}/start")Teleconsultation st(@PathVariable Long id){return s.start(id);}@PostMapping("/teleconsultations/{id}/complete")Teleconsultation f(@PathVariable Long id){return s.complete(id);}}